Given an array of n-positive elements. The sub-array sum is defined as the sum of all elements of a particular sub-array, the task is to find the sum of all unique sub-array sum. Note: Unique Sub-array sum means no other sub-array will have the same sum value. Examples:Input : arr[] = {3, 4, 5} Output : 40 Explanation: All possible unique sub-array with their sum are as: (3), (4), (5), (3+4), (4+5), (3+4+5). Here all are unique so required sum = 40Input : arr[] = {2, 4, 2} Output : 12 Explanation: All possible unique sub-array with their sum are as: (2), (4), (2), (2+4), (4+2), (2+4+2). Here only (4) and (2+4+2) are unique.[Naive Approach] - Sorting - O(n2 Log n) Time and O(n2) SpaceCalculate the cumulative sum of an array. Store all sub-array sum in vector. Sort the vector. Mark all duplicate sub-array sum to zero Calculate and return totalSum.
            C++

    #include <bits/stdc++.h>
using namespace std;

int findSubarraySum(vector<int> &arr) {
    int n = arr.size();
    vector<int> subArrSum;

    // Generate all subarray sums and store them in a vector
    for (int i = 0; i < n; i++) {
        int sum = 0;
        for (int j = i; j < n; j++) {
            sum += arr[j];
            subArrSum.push_back(sum);
        }
    }

    // Sort the vector to group duplicate sums together
    sort(subArrSum.begin(), subArrSum.end());

    // Sum only unique subarray sums
    int m = subArrSum.size();
    int totalSum = 0;

    if (m == 1) return subArrSum[0];

    // Explicitely handle the first element
    if (subArrSum[0] != subArrSum[1])
        totalSum += subArrSum[0];

    // Process Middle Elements
    for (int i = 1; i < m - 1; i++) {
        if (subArrSum[i] != subArrSum[i+1] && 
            subArrSum[i] != subArrSum[i-1]) {
            totalSum += subArrSum[i];
        }
    }

    // Explicitely handle the last element
    if (subArrSum[m-1] != subArrSum[m-2])
        totalSum += subArrSum[m-1];

    return totalSum;
}

int main() {
    vector<int> arr = {3, 2, 3, 1, 4};
    cout << findSubarraySum(arr); 
    return 0;
}


