long long int findSubarraySum(vector<int>& arr)
{
	long long int res = 0;

	// Go through all subarrays, compute sums
	// and count occurrences of sums.
	unordered_map<int, int> m;
	int n = arr.size();
	for (int i = 0; i < n; i++) {
		int sum = 0;
		for (int j = i; j < n; j++) {
